"""Bullet cues generated by Claude Code agents instead of the API (Kian, 2026-11-10).

    uv run --no-sync python scripts/bullet_cue_agents.py dump [--split dev|test] [--prompt P]
    uv run --no-sync python scripts/bullet_cue_agents.py ingest --run <run_id> [--split ...] \
        [--prompt P]

``dump`` writes one job file per unit of the split (TEST: ``data/private/reader/cue_jobs/``;
DEV: ``cue_jobs_dev/``) holding exactly what the API condition sent (prompt ``P``, default
``bullet_cue.v2``; ``bullet_cue.v3`` is the stricter "stated" rule): every notes bullet, then
per bullet its parents and its aligned span widened by ``PAD`` lines. Alignment: TEST uses the
hand maps; DEV (IS1008a) has none and uses ``overlap_align``, the word-overlap window the API
pilot used. An agent answers each bullet with one JSON line
``{"bullet_id": ..., "found": [...], "cues": [...]}`` in the :class:`tenor.evals.bullet_cues.CueOut`
shape, into ``cue_agent_runs/<run>/<meeting>__<product>.jsonl``. ``ingest`` validates those
lines, checks every quote against its span (``cue_rows``), and writes the condition-blind reader
packets and the key (``build_packets``) plus the local rows. Local data only: no LLM, no network.
"""

from __future__ import annotations

import argparse
import json
from datetime import UTC, datetime
from pathlib import Path
from typing import Any

from tenor.evals import bullet_cues as B
from tenor.evals import coverage_e4 as C4

READERS = Path("data/private/reader")
MAPS = Path("data/private/feature_tests/map")
OUT = READERS / "cue_agent_runs"
MODEL = "agent"


def jobs_dir(split: str) -> Path:
    return READERS / ("cue_jobs" if split == "test" else f"cue_jobs_{split}")


def setup(split: str) -> tuple[list[B.CueUnit], dict[str, list[B.Job]]]:
    """The split's units and each unit's jobs (alignment per ``B.split_alignment``)."""
    units, align = B.split_units(READERS / "packets", MAPS, split, C4.TEST_MEETINGS)
    return units, {u.key: B.jobs_for(u, align[u.key]) for u in units}


def dump(split: str, prompt: str) -> None:
    units, jobs = setup(split)
    out = jobs_dir(split)
    out.mkdir(parents=True, exist_ok=True)
    text = Path(f"prompts/{prompt}.md").read_text(encoding="utf-8")
    for u in units:
        body = B.job_file(u, jobs[u.key], text, "Cue jobs")
        (out / f"{u.meeting_id}__{u.product}.md").write_text(body, encoding="utf-8")
        print(f"{u.key}: {len(jobs[u.key])} jobs")
    align = "hand maps" if split == "test" else "overlap_align (word overlap; no hand map on DEV)"
    print(f"{sum(map(len, jobs.values()))} jobs in {out} (prompt {prompt}; alignment {align})")


def ingest(run: str, seed: int, split: str, prompt: str) -> None:
    units, jobs = setup(split)
    rows: list[dict[str, Any]] = []
    errors: list[str] = []
    for u in units:
        path = OUT / run / f"{u.meeting_id}__{u.product}.jsonl"
        if not path.exists():
            errors.append(f"{u.key}: no output")
            continue
        by_id = {j.bullet_id: j for j in jobs[u.key]}
        lines, errs = B.read_agent_lines(path.read_text(encoding="utf-8"), by_id, u.key)
        errors += errs
        for bid, d in lines:
            try:
                out = B.CueOut.model_validate(d)
            except ValueError as e:
                errors.append(f"{u.key} {bid}: {e}")
                continue
            rows.append({"unit": u.key, "bullet_id": bid, "model": MODEL,
                         "found": [f.model_dump() for f in out.found],
                         "cues": B.cue_rows(by_id[bid], out)})  # fmt: skip
    texts, key_units = B.build_packets(units, rows, {}, seed)
    pdir = READERS / "cue_packets" / run
    pdir.mkdir(parents=True, exist_ok=True)
    for name, text in texts.items():
        (pdir / name).write_text(text, encoding="utf-8")
    kdir = READERS / "cue_keys"
    kdir.mkdir(parents=True, exist_ok=True)
    key = {"meta": {"key_version": B.KEY_VERSION, "packet_version": B.PACKET_VERSION,
                    "reader_prompt": B.READER_PROMPT, "seed": seed, "run_id": run,
                    "split": split, "models": [MODEL], "prompt": prompt,
                    "alignment": "hand maps" if split == "test" else "overlap_align",
                    "date": datetime.now(UTC).isoformat(timespec="seconds")},
           "units": key_units}  # fmt: skip
    (kdir / f"{run}.key.json").write_text(json.dumps(key, indent=1, ensure_ascii=False) + "\n")
    (OUT / run).mkdir(parents=True, exist_ok=True)
    (OUT / run / "rows.json").write_text(json.dumps(rows, indent=1, ensure_ascii=False) + "\n")
    ok = sum(1 for r in rows for c in r["cues"] if c["status"] == "ok")
    bad = sum(1 for r in rows for c in r["cues"] if c["status"] != "ok")
    print(f"{len(rows)} bullets, {ok} cues ok, {bad} failed checks; packets {pdir}")
    print(f"items to read: {sum(len(u['items']) for u in key_units.values())}")
    for e in errors:
        print("ERROR", e)


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    sub = ap.add_subparsers(dest="cmd", required=True)
    for name in ("dump", "ingest"):
        p = sub.add_parser(name)
        p.add_argument("--split", choices=("dev", "test"), default="test")
        p.add_argument("--prompt", default=B.PROMPT)
        if name == "ingest":
            p.add_argument("--run", required=True)
            p.add_argument("--seed", type=int, default=42)
    a = ap.parse_args()
    if a.cmd == "dump":
        dump(a.split, a.prompt)
    else:
        ingest(a.run, a.seed, a.split, a.prompt)
